'use strict';
const $=id=>document.getElementById(id),C=OriginCommands;
let vm=null,running=false,ready=false,busy=false,output='',font=16,bootTimer=null,marker='',inMarker=false,pending=null,queue=[],files=[],confirmation=null;
const commandControls=()=>[$('command'),$('send'),$('make-file'),$('refresh-files'),...document.querySelectorAll('[data-command]')];
function state(message){$('status').textContent=message;$('light').classList.toggle('running',running);$('start').disabled=busy||running;$('start').textContent=vm?'Resume':'Start VM';$('pause').disabled=busy||!running;$('restart').disabled=busy||!vm;commandControls().forEach(el=>el.disabled=busy||!ready||!running);}
function render(){ $('terminal').textContent=output;$('terminal').scrollTop=$('terminal').scrollHeight; }
function pump(){if(!pending&&queue.length&&ready&&running){pending=queue.shift();pending.response='';pending.timer=setTimeout(()=>{const p=pending;pending=null;p.reject(new Error('Guest response timed out. Restart if the CPU was halted.'));pump();},8000);vm.serial0_send(pending.command+'\n');}}
function raw(command){return new Promise((resolve,reject)=>{queue.push({command,resolve,reject});pump();});}
function cancelQueue(){if(pending){clearTimeout(pending.timer);pending.reject(new Error('VM restarted'));pending=null;}for(const p of queue)p.reject(new Error('VM restarted'));queue=[];}
function acceptByte(byte){if(byte===30){inMarker=true;marker='';return;}if(inMarker){if(byte===31){inMarker=false;if(marker==='ORIGIN_READY')onPrompt();return;}marker+=String.fromCharCode(byte);return;}const ch=String.fromCharCode(byte);if(pending)pending.response+=ch;if(ch==='\r')return;if(ch==='\b')output=output.slice(0,-1);else output+=ch;output=output.slice(-80000);render();if(output.endsWith('CPU halted. Close the VM to stop it.\n')){ready=false;state('Guest halted. Restart to continue.');}}
function onPrompt(){const completed=pending;if(completed){pending=null;clearTimeout(completed.timer);completed.resolve(completed.response);}if(!ready){ready=true;clearTimeout(bootTimer);state('Kernel ready');$('command').focus();queueMicrotask(()=>refreshFiles().catch(showError));}pump();}
function showError(error){$('operation-status').textContent=String(error.message||error);}
async function start(){if(busy||running)return;busy=true;state('Starting…');try{if(vm){await vm.run();running=true;busy=false;state(ready?'Kernel ready':'Booting kernel…');pump();return;}output='';render();ready=false;running=true;inMarker=false;marker='';vm=new V86({wasm_path:'vendor/v86.wasm',memory_size:32*1024*1024,vga_memory_size:2*1024*1024,bios:{url:'vendor/seabios.bin'},vga_bios:{url:'vendor/vgabios.bin'},hda:{url:'assets/origin.img',async:false},screen_container:$('screen'),autostart:true,disable_keyboard:false,disable_mouse:false,disable_speaker:true});vm.keyboard_set_enabled(false);vm.mouse_set_enabled(false);vm.add_listener('serial0-output-byte',acceptByte);bootTimer=setTimeout(()=>{if(!ready)state('Boot not confirmed. Try restarting.');},15000);busy=false;state('Booting kernel…');}catch(error){busy=false;running=false;ready=false;state('Could not start VM');showError(error);}}
async function pause(){if(busy||!vm||!running)return;busy=true;await vm.stop();running=false;busy=false;state('Paused. Select Resume to continue.');}
async function reset(){if(busy||!vm)return;busy=true;state('Resetting…');clearTimeout(bootTimer);cancelQueue();await vm.destroy();vm=null;running=false;ready=false;busy=false;files=[];renderFiles();await start();}
function renderFiles(){$('file-list').replaceChildren();if(!files.length){$('file-list').textContent=ready?'No files in RAM.':'Start the VM to see your files.';return;}for(const file of files){const row=document.createElement('div');row.className='file-row';const name=document.createElement('span');name.textContent=file.name+' · '+file.bytes+' bytes';const read=document.createElement('button');read.textContent='Read';read.addEventListener('click',()=>dispatch('r '+file.name));const remove=document.createElement('button');remove.textContent='Delete';remove.addEventListener('click',()=>dispatch('delete '+file.name));row.append(name,read,remove);$('file-list').append(row);}}
async function refreshFiles(){if(!ready||!running)return;const response=await raw('ls');files=[...response.matchAll(/^([A-Za-z0-9_.-]+)  (\d+) bytes\r?$/gm)].map(m=>({name:m[1],bytes:Number(m[2])}));renderFiles();}
async function openFile(name=''){if(!ready||!running)return;try{await refreshFiles();$('filename').value=name||C.nextFilename(files);$('file-text').value='';$('file-error').textContent='';if(!$('file-dialog').open)$('file-dialog').showModal();$('filename').focus();$('filename').select();}catch(e){showError(e);}}
async function doCommand(command){try{if(!/^[\x20-\x7e]{1,639}$/.test(command))throw new Error('Use at most 639 printable ASCII characters.');if(command==='halt'){vm.serial0_send('halt\n');return;}let response=await raw(command);if(/^rm\b/.test(command)&&response.includes('Type yes or no.'))response=await raw('yes');$('operation-status').textContent=response.replace(/^.*?\r?\n/,'').replace(/origin>\s*$/,'').trim().slice(0,260)||'Done.';if(/^(write|new|rm)\b/.test(command))await refreshFiles();}catch(e){showError(e);}}
async function dispatch(text){if(!vm||!ready||!running)return;const result=C.resolve(text);if(result.kind==='empty')return;if(result.kind==='create'){openFile(result.name);return;}if(result.kind==='unsupported'){$('interpretation').textContent=result.message;showSuggestions(result.suggestions);return;}$('interpretation').textContent=(result.correction?'Corrected '+result.correction+' → ':'Will run: ')+result.command;$('command').value='';const first=result.command.split(' ')[0],name=result.command.split(' ')[1];if(first==='rm'||first==='halt'||(first==='write'&&files.some(f=>f.name===name))){confirmation=result.command;$('action-detail').textContent='Run “'+result.command+'”? '+(first==='halt'?'This stops the guest CPU.':first==='rm'?'This removes a RAM file.':'This replaces an existing RAM file.');$('action-dialog').showModal();return;}await doCommand(result.command);}
function showSuggestions(items){$('suggestions').replaceChildren();for(const value of items){const button=document.createElement('button');button.type='button';button.textContent=value;button.addEventListener('click',()=>{$('command').value=value;updateSuggestions();$('command').focus();});$('suggestions').append(button);}}
function updateSuggestions(){const value=$('command').value,result=C.resolve(value);$('interpretation').textContent=result.kind==='command'?(result.correction?'Correction: '+result.correction+' → ':'Will run: ')+result.command:result.kind==='create'?'Opens the safe file creator.':result.message||'Local suggestions. No neural model is running yet.';showSuggestions(result.suggestions||C.suggestions(value));}
const labels=[['h','Help','help'],['a','About','about'],['c','CPU','cpu'],['m','Memory','mem'],['t','Tests','selftest'],['l','Files','ls'],['r','Read','cat '],['w','Write','write '],['n','New','new '],['d','Delete','rm '],['b','Bytes','alloc '],['e','Echo','echo '],['x','Clear','clear'],['q','Halt','halt']];
for(const [key,title,command] of labels){const b=document.createElement('button');b.type='button';b.dataset.command=command;b.disabled=true;const k=document.createElement('kbd');k.textContent=key;b.append(k,title);b.addEventListener('click',()=>{if(command.endsWith(' ')){$('command').value=key+' ';updateSuggestions();$('command').focus();}else dispatch(command);});$('command-bar').append(b);}
$('start').addEventListener('click',start);$('pause').addEventListener('click',pause);$('restart').addEventListener('click',()=>{if(!busy&&vm)$('reset-dialog').showModal();});$('cancel-reset').addEventListener('click',()=>$('reset-dialog').close());$('confirm-reset').addEventListener('click',()=>{$('reset-dialog').close();reset();});
$('command-form').addEventListener('submit',e=>{e.preventDefault();dispatch($('command').value);});$('command').addEventListener('input',updateSuggestions);$('command').addEventListener('keydown',e=>{if(e.key==='Tab'&&$('command').value){e.preventDefault();const values=C.suggestions($('command').value);if(values.length){$('command').value=values[0];updateSuggestions();}}});
document.querySelectorAll('.launchpad [data-command]').forEach(b=>b.addEventListener('click',()=>dispatch(b.dataset.command)));
$('make-file').addEventListener('click',()=>openFile());$('refresh-files').addEventListener('click',()=>refreshFiles().catch(showError));$('cancel-file').addEventListener('click',()=>$('file-dialog').close());$('suggest-name').addEventListener('click',async()=>{await refreshFiles();$('filename').value=C.nextFilename(files);});
$('file-form').addEventListener('submit',async e=>{e.preventDefault();const name=$('filename').value.trim(),text=$('file-text').value;if(!/^[A-Za-z0-9_.-]{1,31}$/.test(name)){$('file-error').textContent='Use 1–31 letters, numbers, dots, underscores or hyphens.';return;}if(!/^[\x20-\x7e]{0,511}$/.test(text)){$('file-error').textContent='This prototype supports one line of up to 511 printable ASCII characters.';return;}$('create-file').disabled=true;try{const response=await raw('new '+name+' '+text);if(!response.includes('Saved to RAM only.'))throw new Error(response.replace(/^.*?\n/,'').replace(/origin>\s*$/,'').trim());$('file-dialog').close();await refreshFiles();$('operation-status').textContent='Created '+name+' in RAM. It disappears on restart.';}catch(error){$('file-error').textContent=error.message;}finally{$('create-file').disabled=false;}});
$('cancel-action').addEventListener('click',()=>{confirmation=null;$('action-dialog').close();});$('confirm-action').addEventListener('click',()=>{const value=confirmation;confirmation=null;$('action-dialog').close();if(value)doCommand(value);});
$('larger').addEventListener('click',()=>{font=Math.min(26,font+2);document.documentElement.style.setProperty('--terminal-size',font+'px');});$('smaller').addEventListener('click',()=>{font=Math.max(12,font-2);document.documentElement.style.setProperty('--terminal-size',font+'px');});$('download-log').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([output||'VM not started.\n'],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='familiar-origin-console.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&running&&!pending)pause();});window.addEventListener('error',e=>showError(e.error||e.message));

function releaseInput(){if(vm){vm.keyboard_set_enabled(false);vm.mouse_set_enabled(false);}$('input-status').textContent='Browser controls active.';}
$('screen').addEventListener('mouseenter',()=>{if(vm&&running)vm.mouse_set_enabled(true);});
$('screen').addEventListener('mouseleave',()=>{if(vm)vm.mouse_set_enabled(false);});
$('screen').addEventListener('click',()=>{if(vm&&running){$('screen').focus();vm.keyboard_set_enabled(true);$('input-status').textContent='Guest keyboard active. Escape releases it.';}});
$('screen').addEventListener('blur',releaseInput);
$('screen').addEventListener('keydown',e=>{if(e.key==='Escape'){releaseInput();$('command').focus();}},true);
$('release-input').addEventListener('click',()=>{releaseInput();$('command').focus();});
